def knapSack(W, wt, val, n):

    # base case
    if n == 0 or W == 0:
        return 0

    # If weight of the nth item is more than W, 
    # then this item cannot be included in the optimal solution.
    if (wt[n-1] > W):
        return knapSack(W, wt, val, n-1)

    # If we keep the nth item, then weight of the knapsack will be 
    # reduced by wt[n-1] and the value will be increased by val[n-1]
    if (val[n-1] > 0 and wt[n-1] <= W):

        # Return the maximum of two cases: 
        # (1) nth item included 
        # (2) nth item not included 
        return max(knapSack(W-wt[n-1], wt, val, n-1),
                   knapSack(W, wt, val, n-1))

    # If we discard the nth item, then return as we are left with 
    # only the items from the starting to the (n-1)th item 
    else:
        return knapSack(W, wt, val, n-1)

